(function(root){'use strict';
const csv=typeof module!=='undefined'?require('./csv.js'):root.Csv,hard=typeof module!=='undefined'?require('./hard-rules.js'):root.HardRules;
const NUMERIC=['trip_fuel','crew_duty_elapsed','holding_turbulence','eta','fuel','reserve','burn_per_min','cruise_burn_per_min','cruise_speed_kts','approach_speed_kts','destination_fuel','alternate_approach_fuel','alternate_approach_minutes','turnaround','next_departure','next_flight_minutes','crew_duty_remaining','crew_flight_remaining','current_flight_remaining','connections','connection_departure'];
const FIELDS=['original_stand','callsign','carrier','origin','destination','aircraft_type','operation','wake','runway',...NUMERIC,'alternate_id','alternate_required','weather_assessed','weather_severe','weather_clearance_miles'];
function clone(x){return JSON.parse(JSON.stringify(x));}
function airportScenario(base,dest,catalog){const airport=catalog[dest];if(!airport)throw Error('Airport '+dest+' is not in the provided coordinate lookup. No alternate-distance check can be verified.');const s=clone(base);s.airport=dest;s.airport_position=airport.position;s.airport_name=airport.name;s.airport_city=airport.city;
s.alternate_options=Object.values(catalog).filter(a=>a.id!==dest).sort((a,b)=>hard.distanceNm(airport.position,a.position)-hard.distanceNm(airport.position,b.position)).slice(0,5).map(a=>({id:a.id,position:a.position,available:true,availability_source:'Explicit demonstration assumption, not live airport status'}));return s;}
function dotScenario(base,records,catalog){if(!records.length)throw Error('Select at least one flight.');if(records.length>12)throw Error('Select at most 12 flights per run.');const rows=records.map(r=>r.row),dest=rows[0].DESTINATION_AIRPORT.trim().toUpperCase();if(rows.some(r=>!r.AIRLINE?.trim()||!r.FLIGHT_NUMBER?.trim()||!r.ORIGIN_AIRPORT?.trim()))throw Error('A selected DOT row is missing airline, flight number or origin.');
if(rows.some(r=>r.DESTINATION_AIRPORT.trim().toUpperCase()!==dest))throw Error('One run must use a single destination airport.');const times=rows.map(r=>csv.time(r.SCHEDULED_ARRIVAL));if(times.some(t=>t===undefined))throw Error('A scheduled arrival time is invalid.');
if(rows.some(r=>String(r.YEAR)!=='2015'))throw Error('The challenge DOT seed must come from 2015.');const qualifying=rows.find(r=>csv.num(r.WEATHER_DELAY)>15||csv.num(r.LATE_AIRCRAFT_DELAY)>20);if(!qualifying)throw Error('Include at least one DOT seed with WEATHER_DELAY > 15 or LATE_AIRCRAFT_DELAY > 20.');const s=airportScenario(base,dest,catalog),start=Math.min(...times);s.base_local_minutes=start;s.date=[rows[0].YEAR,rows[0].MONTH.padStart(2,'0'),rows[0].DAY.padStart(2,'0')].join('-');s.flights=rows.map((r,i)=>{const template=clone(base.flights[Math.min(i,base.flights.length-1)]),eta=times[i]-start;return {...template,holding_turbulence:template.holding_turbulence??1,id:'F'+(i+1),callsign:r.AIRLINE+r.FLIGHT_NUMBER,carrier:r.AIRLINE,origin:r.ORIGIN_AIRPORT,eta,alternate:clone(s.alternate_options[0]),next_departure:eta+55,connection_departure:eta+80,source:'DOT schedule; operational values use the explicitly applied demo profile',historical:{row:records[i].index,weather_delay:csv.num(r.WEATHER_DELAY),late_aircraft_delay:csv.num(r.LATE_AIRCRAFT_DELAY),distance_miles:csv.num(r.DISTANCE),trip_fuel:(csv.num(r.SCHEDULED_TIME)!==undefined?Math.max(0,csv.num(r.SCHEDULED_TIME)-15):((csv.num(r.DISTANCE)||0)/1.15078/template.cruise_speed_kts*60))*template.cruise_burn_per_min}};});
s.provenance={historical:'Selected DOT flight identities, flight date and scheduled local arrival times. Recorded delay causes identify the seed; realised arrival times are not decision inputs.',simulated:'Explicitly applied demo operations profile for ALL aircraft type/wake, fuel, burn, weather assessments, runways, stands, crew, connections, alternate availability and turnaround inputs.',grouping:'Same flight-date row and destination, scheduled arrivals within ±60 minutes of the seed. Overnight and timezone rollover need review.'};s.historical_seed=clone(qualifying);s.source_label='DOT CSV + demo operations profile';return s;}
function operationalScenario(base,records,catalog,{useDefaults=false,destination=base.airport}={}){if(!records.length||records.length>12)throw Error('Select 1–12 flights.');const rows=records.map(r=>r.row),dests=[...new Set(rows.map(r=>String(r.DESTINATION||r.DESTINATION_AIRPORT||destination).trim().toUpperCase()))];if(dests.length!==1)throw Error('Select flights for a single destination.');const s=airportScenario(base,dests[0],catalog);
s.flights=rows.map((r,i)=>{const f=useDefaults?clone(base.flights[Math.min(i,base.flights.length-1)]):{weather:{}};f.id='F'+(i+1);f.weather=f.weather||{};
for(const k of NUMERIC)if(Object.hasOwn(r,k.toUpperCase()))f[k]=csv.num(r[k.toUpperCase()]);
for(const k of ['original_stand','callsign','carrier','origin','aircraft_type','operation','wake','runway'])if(Object.hasOwn(r,k.toUpperCase())){const value=r[k.toUpperCase()].trim();f[k]=['operation','wake'].includes(k)?value.toLowerCase():value.toUpperCase();}
if(Object.hasOwn(r,'ALTERNATE_REQUIRED'))f.alternate_required=csv.boolean(r.ALTERNATE_REQUIRED);
for(const [k,h] of [['assessed','WEATHER_ASSESSED'],['severe','WEATHER_SEVERE']])if(Object.hasOwn(r,h))f.weather[k]=csv.boolean(r[h]);
if(Object.hasOwn(r,'WEATHER_CLEARANCE_MILES'))f.weather.clearance_miles=csv.num(r.WEATHER_CLEARANCE_MILES);
if(Object.hasOwn(r,'ALTERNATE_ID')){const alt=catalog[r.ALTERNATE_ID.trim().toUpperCase()];f.alternate=alt?{id:alt.id,position:alt.position,available:true,availability_source:'Shared imported scenario assumption'}:undefined;}else if(useDefaults)f.alternate=clone(s.alternate_options[0]);
f.source=useDefaults?'Operational CSV; absent columns use an explicitly applied demo profile. Blank cells stay unknown.':'Operational CSV; missing/blank fields remain unknown and block validation.';return f;});
s.source_label=useDefaults?'Operational CSV + declared defaults':'Operational CSV';s.provenance={import:'User-supplied operational CSV. Aircraft and operational inputs are user assertions, not independently verified.',shared:'Airport geometry, alternate availability and shared resources use the displayed simulation profile.',missing:'Without explicit defaults, missing required flight fields remain unknown. Blank provided cells never silently use defaults.'};return s;}
function template(s){const q=v=>'"'+String(v??'').replaceAll('"','""')+'"';const header=FIELDS.map(k=>k.toUpperCase());const lines=[header.map(q).join(',')];for(const f of s.flights){const r={...f,destination:s.airport,alternate_id:f.alternate?.id,weather_assessed:f.weather?.assessed,weather_severe:f.weather?.severe,weather_clearance_miles:f.weather?.clearance_miles};lines.push(FIELDS.map(k=>q(r[k])).join(','));}return '\ufeff'+lines.join('\r\n')+'\r\n';}
function newFlight(s,index){const f=clone(s.flights.at(-1));f.id='F'+index;f.callsign='SIM'+String(index).padStart(3,'0');f.carrier='SIM';f.eta=Math.min(120,Math.max(...s.flights.map(f=>f.eta||0))+3);f.fuel=6000;f.holding_turbulence=f.holding_turbulence??1;f.next_departure=f.eta+55;f.connection_departure=f.eta+80;f.source='Added synthetic flight using the displayed demo operations profile.';delete f.historical;return f;}
root.ScenarioIO={clone,airportScenario,dotScenario,operationalScenario,template,newFlight,NUMERIC,FIELDS};if(typeof module!=='undefined')module.exports=root.ScenarioIO;
})(typeof window!=='undefined'?window:globalThis);
